<script setup lang="ts">
import { SearchableSelect } from '#components'
const { t } = useLanguage()
const db=useSupabase(),auth=useAuth(),month=ref(nowMonth()),memberships=ref<any[]>([]),requests=ref<any[]>([]),reviews=ref<any[]>([]),audit=ref<any[]>([]),error=ref(''),success=ref(''),busy=ref(false)
const form=reactive({membership:'',teacher:0,office:0,reason:''})
const selected=computed(()=>memberships.value.find(r=>r.id===form.membership))
async function load(){if(!db)return;busy.value=true;error.value='';try{const report=await db.rpc('class_month_report',{p_month:monthStart(month.value)});if(report.error)throw report.error;memberships.value=report.data.rows;requests.value=await allRows(()=>db.from('membership_financial_adjustments').select('*').order('created_at',{ascending:false}).order('id'));if(auth.profile.value?.role==='admin'){reviews.value=await allRows(()=>db.from('migration_review_items').select('*').is('resolved_at',null).order('id'));const q=await db.from('audit_logs').select('id,table_name,action,row_id,actor_id,created_at,reason').order('id',{ascending:false}).limit(100);if(q.error)throw q.error;audit.value=q.data||[]}}catch(e){error.value=errText(e)}finally{busy.value=false}}
function select(){form.teacher=Number(selected.value?.teacher_entitlement||0);form.office=Number(selected.value?.center_entitlement||0)}
async function submit(){if(!db||busy.value)return;busy.value=true;error.value='';try{const q=await db.rpc('request_membership_adjustment',{p_membership:form.membership,p_teacher:form.teacher,p_office:form.office,p_reason:form.reason});if(q.error)throw q.error;success.value=t('financialUi.adjustments.requestSaved');form.reason='';await load()}catch(e){error.value=errText(e)}finally{busy.value=false}}
async function review(r:any,approve:boolean){if(!db||busy.value)return;const note=window.prompt(t('financialUi.adjustments.managerNotePrompt'));if(!note)return;busy.value=true;try{const q=await db.rpc('review_membership_adjustment',{p_id:r.id,p_approve:approve,p_note:note});if(q.error)throw q.error;success.value=t('financialUi.adjustments.decisionSaved');await load()}catch(e){error.value=errText(e)}finally{busy.value=false}}
async function resolve(r:any){if(!db||busy.value)return;const note=window.prompt(t('financialUi.adjustments.resolutionPrompt'));if(!note)return;busy.value=true;try{const q=await db.rpc('resolve_migration_review',{p_id:r.id,p_resolution:note});if(q.error)throw q.error;await load()}catch(e){error.value=errText(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template><div><PageTitle :title="t('financialUi.adjustments.title')" :subtitle="t('financialUi.adjustments.subtitle')"><button class="btn" :disabled="busy" @click="load">{{ t('financialUi.refresh') }}</button></PageTitle><Notice :message="error" kind="error"/><Notice :message="success" kind="success"/><section class="card"><form @submit.prevent="submit"><div class="form-grid"><label>{{ t('financialUi.month') }}<input v-model="month" type="month" required @change="load"/></label><label>{{ t('financialUi.adjustments.account') }}<SearchableSelect v-model="form.membership" :options="memberships" label-key="student_name" :search-keys="['student_code','class_name']" :placeholder="t('financialUi.adjustments.selectAccount')" :min-chars="2" @update:model-value="select"><template #option="{option}">{{option.student_name}} · {{option.student_code}} · {{option.class_name}}</template></SearchableSelect></label><label>{{ t('financialUi.adjustments.proposedTeacher') }}<input v-model.number="form.teacher" type="number" min="0" step="0.01" required/></label><label>{{ t('financialUi.adjustments.proposedOffice') }}<input v-model.number="form.office" type="number" min="0" step="0.01" required/></label><label class="wide">{{ t('financialUi.adjustments.requestReason') }}<textarea v-model="form.reason" minlength="4" required/></label></div><p v-if="selected">{{ t('financialUi.adjustments.paidAmount') }}: {{money(selected.amount_due)}} · {{ t('financialUi.adjustments.proposedTotal') }}: {{money(form.teacher+form.office)}}</p><div class="form-footer"><button class="btn primary" :disabled="busy">{{ t('financialUi.adjustments.requestApproval') }}</button></div></form></section><section class="card" style="margin-top:20px"><h3>{{ t('financialUi.adjustments.requestHistory') }}</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>{{ t('financialUi.adjustments.dateAccount') }}</th><th>{{ t('financialUi.adjustments.teacherBeforeAfter') }}</th><th>{{ t('financialUi.adjustments.officeBeforeAfter') }}</th><th>{{ t('financialUi.reason') }}</th><th>{{ t('financialUi.status') }}</th><th>{{ t('financialUi.adjustments.decision') }}</th></tr></thead><tbody><tr v-for="r in requests" :key="r.id"><td>{{r.created_at.slice(0,10)}}<small class="material-id">{{r.monthly_membership_id}}</small></td><td>{{money(r.previous_teacher_entitlement)}} ← {{money(r.new_teacher_entitlement)}}</td><td>{{money(r.previous_office_entitlement)}} ← {{money(r.new_office_entitlement)}}</td><td>{{r.adjustment_reason}}<p>{{r.review_note}}</p></td><td>{{r.approval_status==='pending'?t('financialUi.adjustments.waitingApproval'):r.approval_status==='approved'?t('financialUi.approved'):t('financialUi.rejected')}}</td><td><template v-if="auth.profile.value?.role==='admin'&&r.approval_status==='pending'"><button class="btn small-btn" :disabled="busy" @click="review(r,true)">{{ t('financialUi.adjustments.approve') }}</button> <button class="btn small-btn danger" :disabled="busy" @click="review(r,false)">{{ t('financialUi.adjustments.reject') }}</button></template><small v-else>{{r.approved_by||'—'}}</small></td></tr></tbody></table></div></section>
<template v-if="auth.profile.value?.role==='admin'"><section class="card" style="margin-top:20px"><h3>{{ t('financialUi.adjustments.historicalReview') }}</h3><p class="hint">{{ t('financialUi.adjustments.reviewGuidance') }}</p><div v-for="r in reviews" :key="r.id" class="quick-item"><div><strong>{{r.issue}}</strong><small class="material-id">{{r.table_name}} · {{r.row_id}}</small><details><summary>{{ t('financialUi.adjustments.itemDetails') }}</summary><pre style="white-space:pre-wrap;direction:ltr">{{JSON.stringify(r.details,null,2)}}</pre></details></div><button class="btn small-btn" :disabled="busy" @click="resolve(r)">{{ t('financialUi.adjustments.recordReview') }}</button></div><p v-if="!reviews.length">{{ t('financialUi.adjustments.noOpenItems') }}</p></section><section class="card" style="margin-top:20px"><h3>{{ t('financialUi.adjustments.recentChanges') }}</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>{{ t('financialUi.adjustments.time') }}</th><th>{{ t('financialUi.adjustments.tableDocument') }}</th><th>{{ t('financialUi.adjustments.action') }}</th><th>{{ t('financialUi.adjustments.user') }}</th><th>{{ t('financialUi.reason') }}</th></tr></thead><tbody><tr v-for="r in audit" :key="r.id"><td>{{r.created_at}}</td><td>{{r.table_name}}<small class="material-id">{{r.row_id}}</small></td><td>{{r.action}}</td><td>{{r.actor_id||'migration'}}</td><td>{{r.reason||'—'}}</td></tr></tbody></table></div></section></template></div></template>
